import ngcActionContents from "@carbonFootprint/data/ngc-action-contents.json";
import { ActionContent } from "@carbonFootprint/domain/entities/action/ActionContent";
import { ActionContentsRepository } from "@carbonFootprint/domain/repositories/actionContents.repository";

const NGC_ACTIONS_URL = "https://nosgestesclimat.fr/actions/";

type NgcActionContent = {
  path: string;
  description: string;
  tips?: string;
  benefits?: string;
};

/** Generated by `scripts/fetch-ngc-action-contents.mjs`, keyed by action id. */
const contents: Record<string, NgcActionContent> = ngcActionContents;

export class ActionContentsNgcRepository implements ActionContentsRepository {
  fetchActionContent(actionId: string): ActionContent | undefined {
    const content = contents[actionId];
    if (!content) return undefined;
    return {
      description: content.description,
      tips: content.tips,
      benefits: content.benefits,
      detailsUrl: `${NGC_ACTIONS_URL}${content.path}`,
    };
  }
}
